import {nextDate,recurrenceFor,scheduledIndex} from './schedule.js';
const DAY=86400000,id=()=>globalThis.crypto.randomUUID();
export function nextRepeat(m,originalAt=m.dueAt){if(m.repeatable||m.recurrenceStopped||!m.dueAt)return null;const r=recurrenceFor(m),index=originalAt===m.dueAt?m.occurrence:scheduledIndex(m,originalAt);if(r.frequency==='none'||index===null||r.end==='count'&&index>=r.count)return null;const dueAt=nextDate({...m,dueAt:originalAt},originalAt);return dueAt?{dueAt,occurrence:index+1,releaseAt:originalAt}:null;}
export function repeatCutoff(m,originalAt=m.dueAt){const next=nextRepeat(m,originalAt);return next?Math.max(Date.parse(originalAt),Date.parse(next.dueAt)-DAY):Infinity;}
export function assertRecurringDeadline(m,deadline,originalAt=m.dueAt){const limit=repeatCutoff(m,originalAt);if(Date.parse(deadline)>limit)throw Error('Keep this deadline at least 24 hours before the next repeat. Latest: '+new Date(limit).toLocaleString());}
export function stopMissionSeries(s,id){const item=s.missions.find(m=>m.id===id);if(!item||s.missions.some(m=>m.seriesId===item.seriesId&&m.occurrence>item.occurrence))return;for(const m of s.missions)if(m.seriesId===item.seriesId){m.recurrenceStopped=true;m.nextRepeat=null;}}
export function failMission(s,missionId,now=new Date(),reason='manual'){const m=s.missions.find(m=>m.id===missionId);if(!m||m.status!=='active')return false;m.status='failed';m.failedAt=new Date(now).toISOString();m.failureReason=reason;m.nextRepeat=nextRepeat(m);s.history.unshift({id:id(),missionId:m.id,type:'fail',title:m.title,at:m.failedAt,reason});return true;}
export function createRepeat(m,next,createdAt=next.releaseAt){return {...structuredClone(m),id:id(),parent:'',status:'active',completedAt:'',failedAt:'',failureReason:'',nextRepeat:null,originalDueAt:'',createdAt:new Date(Math.min(Date.parse(createdAt),Date.parse(next.dueAt)-1)).toISOString(),dueAt:next.dueAt,occurrence:next.occurrence,calendar:{...structuredClone(m.calendar),uid:''},reminderMode:'even',reminderTimes:[],subtasks:m.subtasks.map(t=>({...t,done:false}))};}
export function processMissionLifecycle(s,now=Date.now()){let changed=false;for(let pass=0;pass<1000;pass++){const latest=new Map();for(const m of s.missions){const previous=latest.get(m.seriesId);if(!previous||m.occurrence>previous.occurrence)latest.set(m.seriesId,m);}let progress=false;for(const m of latest.values()){if(m.repeatable||m.recurrenceStopped)continue;for(const o of Object.values(s.calendarOverrides?.[m.seriesId]||{}))if(Date.parse(o.originalAt)>=Date.parse(m.dueAt)){const limit=repeatCutoff(m,o.originalAt);if(Number.isFinite(limit)&&Date.parse(o.deadline)>limit){o.deadline=new Date(limit).toISOString();changed=true;}}if(m.status==='active'&&now>=repeatCutoff(m)){failMission(s,m.id,new Date(repeatCutoff(m)),'repeat-cutoff');progress=changed=true;}if(m.status==='failed'){const next=m.nextRepeat||nextRepeat(m);if(!next)continue;if(!m.nextRepeat){m.nextRepeat=next;changed=true;}if(Date.parse(next.releaseAt)<=now&&s.missions.length<10000){if(!s.missions.some(x=>x.seriesId===m.seriesId&&x.occurrence===next.occurrence))s.missions.push(createRepeat(m,next));m.nextRepeat=null;progress=changed=true;}}}if(!progress)break;}return changed;}
export function validLifecycle(m){const date=v=>v===undefined||v===''||typeof v==='string'&&Number.isFinite(Date.parse(v));return (m.recurrenceStopped===undefined||typeof m.recurrenceStopped==='boolean')&&date(m.failedAt)&&(m.failureReason===undefined||['','manual','repeat-cutoff'].includes(m.failureReason))&&(m.nextRepeat==null||typeof m.nextRepeat==='object'&&date(m.nextRepeat.dueAt)&&!!m.nextRepeat.dueAt&&date(m.nextRepeat.releaseAt)&&!!m.nextRepeat.releaseAt&&Date.parse(m.nextRepeat.dueAt)>Date.parse(m.nextRepeat.releaseAt)&&Number.isInteger(m.nextRepeat.occurrence)&&m.nextRepeat.occurrence===m.occurrence+1);}
